sp_widget.client_script:
function($timeout, $scope) {
  var c = this;
  c.step = 1;
  c.form = { partner_scope: 'global' };
  c.err = {};
  c.busy = false;
  c.copied = false;

  /* ---- I41: submit-time attachments. Queued locally, uploaded AFTER create
     via the platform Attachment API (the record's write-ACL is the authority,
     i30's model). sys_id from the create response is used transiently as the
     upload target and never displayed. ---- */
  c.att = { maxMb: 10, maxFiles: 5, accept: '.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.png,.jpg,.jpeg,.gif,.txt,.csv,.msg,.eml' };
  c.queue = [];
  c.attErr = '';
  c.up = { busy: false, total: 0, done: 0, failed: [] };
  var qSeq = 0;

  c.fileSize = function(n) {
    n = parseInt(n, 10) || 0;
    if (n < 1024) { return n + ' B'; }
    if (n < 1048576) { return Math.round(n / 1024) + ' KB'; }
    return (Math.round(n / 104857.6) / 10) + ' MB';
  };

  function attAllowed(name) {
    var acc = c.att.accept.split(',');
    var dot = String(name || '').lastIndexOf('.');
    if (dot < 0) { return false; }
    var ext = String(name).substring(dot).toLowerCase();
    for (var i = 0; i < acc.length; i++) {
      if (acc[i].trim().toLowerCase() === ext) { return true; }
    }
    return false;
  }

  c.pickFiles = function() {
    var el = document.getElementById('pt-sub-file-input');
    if (el) { el.value = ''; el.click(); }
  };

  c.filesPicked = function(fileList) {
    var files = [], i;
    for (i = 0; i < fileList.length; i++) { files.push(fileList[i]); }
    if (!files.length) { return; }
    $timeout(function() {
      c.attErr = '';
      for (var j = 0; j < files.length; j++) {
        var f = files[j];
        if (c.queue.length >= c.att.maxFiles) {
          c.attErr = 'Up to ' + c.att.maxFiles + ' files per submission.';
          break;
        }
        if (!attAllowed(f.name)) { c.attErr = '"' + f.name + '" is not an accepted file type.'; continue; }
        if (f.size > c.att.maxMb * 1048576) { c.attErr = '"' + f.name + '" is over ' + c.att.maxMb + ' MB.'; continue; }
        var dup = false;
        for (var d = 0; d < c.queue.length; d++) {
          if (c.queue[d].name === f.name && c.queue[d].size === f.size) { dup = true; break; }
        }
        if (dup) { continue; }
        c.queue.push({ key: ++qSeq, name: f.name, size: f.size, file: f });
      }
    });
  };

  c.dequeue = function(entry) {
    if (c.busy) { return; }
    var ix = c.queue.indexOf(entry);
    if (ix > -1) { c.queue.splice(ix, 1); }
    c.attErr = '';
  };

  /* browser -> /api/now/attachment/file; X-UserToken is the session CSRF token */
  function uploadOne(file, sysId) {
    var tok = '';
    try { tok = window.g_ck || (window.NOW && window.NOW.user_token) || ''; } catch (e) {}
    var url = '/api/now/attachment/file?table_name=x_snc_ptag_engage_engagement_request' +
              '&table_sys_id=' + encodeURIComponent(sysId) +
              '&file_name=' + encodeURIComponent(file.name);
    return fetch(url, {
      method: 'POST',
      credentials: 'same-origin',
      headers: {
        'Content-Type': file.type || 'application/octet-stream',
        'X-UserToken': tok,
        'Accept': 'application/json'
      },
      body: file
    }).then(function(res) {
      if (!res.ok) { throw new Error('upload failed (' + res.status + ')'); }
      return res;
    });
  }

  /* per-file failure isolation: the record exists by now, so one bad file must
     not sink the rest. Failures are named on the receipt; the My Engagements
     modal (i30) is the retry surface. */
  function uploadQueue(sysId) {
    if (!c.queue.length) { return; }
    c.up = { busy: true, total: c.queue.length, done: 0, failed: [] };
    var chain = Promise.resolve();
    c.queue.forEach(function(entry) {
      chain = chain.then(function() {
        return uploadOne(entry.file, sysId).then(function() {
          $timeout(function() { c.up.done++; });
        }, function() {
          $timeout(function() { c.up.failed.push(entry.name); });
        });
      });
    });
    chain.then(function() { $timeout(function() { c.up.busy = false; c.queue = []; }); });
  }

  /* ---- reusable modal reference picker ----------------------------------
     ONE parameterized helper set drives the three searchable reference fields;
     c.form holds the picked sys_ids, c.ref the display names for control + review.
     Target geo is a plain select of the controlled regions (data.geos). */
  c.ref = {
    partner:         { name: '' },
    partner_manager: { name: '' },
    primary_product: { name: '' }
  };
  var RP_LABELS = {
    partner: 'Parent Partner',
    partner_manager: 'Partner Manager',
    primary_product: 'What is the Primary Product Used?'
  };
  c.rp = { open: false, key: '', label: '', term: '', items: [], busy: false, hi: -1 };
  var rpTimer = null, rpBrowse = [], rpSeq = 0;

  function rpLock(on) {
    /* body scroll locked while the picker is open */
    try { document.body.classList[on ? 'add' : 'remove']('pt-modal-open'); } catch (e) {}
  }

  function rpSyncHi() {
    /* highlight lands on the already-picked row when it is in the list */
    var sel = c.form[c.rp.key], hi = -1;
    if (sel) {
      for (var i = 0; i < c.rp.items.length; i++) {
        if (c.rp.items[i].id === sel) { hi = i; break; }
      }
    }
    c.rp.hi = hi;
  }

  function rpScrollTo(i) {
    $timeout(function() {
      var list = document.querySelector('.pt-modal__list');
      var el = list && list.children[i];
      if (el && el.scrollIntoView) { el.scrollIntoView({ block: 'nearest' }); }
    }, 0);
  }

  function rpFetch(term, isBrowse) {
    var seq = ++rpSeq;
    c.rp.busy = true;
    c.server.get({ action: 'search', key: c.rp.key, term: term }).then(function(r) {
      if (seq !== rpSeq || !c.rp.open) { return; }
      c.rp.items = (r.data && r.data.matches) || [];
      if (isBrowse) { rpBrowse = c.rp.items; }
      rpSyncHi();
      c.rp.busy = false;
    }, function() {
      if (seq === rpSeq) { c.rp.items = []; c.rp.busy = false; }
    });
  }

  c.rpOpen = function(key) {
    c.rp = { open: true, key: key, label: RP_LABELS[key] || key, term: '', items: [], busy: true, hi: -1 };
    rpBrowse = [];
    rpLock(true);
    rpFetch('', true); /* default browse: first 25 ORDERBYname */
    $timeout(function() {
      var el = document.getElementById('pt-rp-search');
      if (el) { el.focus(); }
    }, 80);
  };

  c.rpTermChange = function() {
    if (rpTimer) { $timeout.cancel(rpTimer); }
    var term = String(c.rp.term || '').trim();
    if (term.length < 2) { c.rp.items = rpBrowse; rpSyncHi(); c.rp.busy = false; return; }
    rpTimer = $timeout(function() { rpFetch(term, false); }, 250);
  };

  c.rpPick = function(m) {
    var key = c.rp.key;
    c.form[key] = m.id;
    c.ref[key].name = m.name;
    if (c.err[key]) { delete c.err[key]; }
    c.rpClose();
  };

  c.rpClear = function(key) {
    c.form[key] = '';
    c.ref[key].name = '';
  };

  c.rpClose = function() {
    if (rpTimer) { $timeout.cancel(rpTimer); }
    rpSeq++;
    rpLock(false);
    c.rp = { open: false, key: '', label: '', term: '', items: [], busy: false, hi: -1 };
  };

  c.rpKeydown = function(ev) {
    var k = ev.keyCode, n = c.rp.items.length;
    if (k === 27) { ev.preventDefault(); ev.stopPropagation(); c.rpClose(); return; }
    if (k === 38 || k === 40) {
      /* arrows navigate the option list */
      ev.preventDefault();
      if (!n) { return; }
      var h = c.rp.hi;
      h = (k === 40) ? ((h + 1) % n) : (h <= 0 ? n - 1 : h - 1);
      c.rp.hi = h;
      rpScrollTo(h);
      return;
    }
    if (k === 13 && c.rp.hi >= 0 && c.rp.hi < n) {
      /* Enter selects the highlighted row */
      ev.preventDefault();
      c.rpPick(c.rp.items[c.rp.hi]);
    }
  };

  /* mandatory mirror of the legacy intake producer's variables (verbatim flags):
     step 1 all five mandatory; step 2 the two descriptions; step 3 none */
  var REQ = {
    1: ['partner', 'partner_manager', 'partner_scope', 'practice', 'target_geo', 'short_description'],
    2: ['idea_description', 'what_is_the_partners_ai_strategy'],
    3: []
  };
  var FLAGS = ['pipeline', 'business_owner', 'executive_sponsor', 'corporate_alignment',
               'budget', 'has_customers', 'certified_resources'];

  function hasVal(v) { return v !== null && v !== undefined && String(v).trim() !== ''; }

  function validate(step) {
    c.err = {};
    var ok = true;
    var req = REQ[step] || [];
    for (var i = 0; i < req.length; i++) {
      if (!hasVal(c.form[req[i]])) { c.err[req[i]] = true; ok = false; }
    }
    if (step === 3 && hasVal(c.form.tam)) {
      var t = parseFloat(String(c.form.tam).replace(/[$,\s]/g, ''));
      if (isNaN(t) || t < 0) { c.err.tam = true; ok = false; }
    }
    return ok;
  }

  /* I42: readiness probes for the subdued button state. Same REQ sets that
     validate() enforces, but NO c.err mutation - the dimming reads state, the
     click still explains it. */
  function stepReady(step) {
    var req = REQ[step] || [];
    for (var i = 0; i < req.length; i++) {
      if (!hasVal(c.form[req[i]])) { return false; }
    }
    if (step === 3 && hasVal(c.form.tam)) {
      var t = parseFloat(String(c.form.tam).replace(/[$,\s]/g, ''));
      if (isNaN(t) || t < 0) { return false; }
    }
    return true;
  }
  c.stepReady = stepReady;

  /* STRY0011976: a field's "required" message clears as soon as the field holds a valid
     value, instead of waiting for the next Continue click. Same rules as validate();
     this only ever removes a flag, validate() is still the only place that sets one. */
  function fieldOk(key) {
    if (key === 'tam') {
      if (!hasVal(c.form.tam)) { return true; }
      var tv = parseFloat(String(c.form.tam).replace(/[$,\s]/g, ''));
      return !isNaN(tv) && tv >= 0;
    }
    return hasVal(c.form[key]);
  }
  $scope.$watchCollection(function() { return c.form; }, function() {
    for (var key in c.err) {
      if (c.err.hasOwnProperty(key) && fieldOk(key)) { delete c.err[key]; }
    }
  });
  c.formReady = function() { return stepReady(1) && stepReady(2) && stepReady(3); };

  c.next = function() { if (validate(c.step)) { c.step = Math.min(3, c.step + 1); toTop(); } };
  c.back = function() { c.err = {}; c.step = Math.max(1, c.step - 1); toTop(); };

  c.nameOf = function(list, id) {
    list = list || [];
    for (var i = 0; i < list.length; i++) { if (list[i].id === id) { return list[i].name; } }
    return '';
  };

  c.signals = function() {
    var n = 0;
    for (var i = 0; i < FLAGS.length; i++) { if (c.form[FLAGS[i]] === true) { n++; } }
    return n;
  };

  c.submit = function() {
    if (c.busy) { return; }
    if (!validate(1)) { c.step = 1; return; }
    if (!validate(2)) { c.step = 2; return; }
    if (!validate(3)) { c.step = 3; return; }
    c.busy = true;
    c.server.get({ action: 'create', form: c.form }).then(function(r) {
      c.data.errors = r.data.errors || [];
      c.data.result = r.data.result || { ok: false };
      if (c.data.result.ok && c.data.result.sys_id) { uploadQueue(String(c.data.result.sys_id)); }  /* I41 */
      c.busy = false;
      toTop();
    }, function() {
      c.busy = false;
      c.data.errors = ['Something went wrong submitting the request. Please try again.'];
    });
  };

  c.reset = function() {
    c.form = { partner_scope: 'global' }; c.err = {}; c.step = 1; c.copied = false;
    c.queue = []; c.attErr = ''; c.up = { busy: false, total: 0, done: 0, failed: [] };  /* I41 */
    for (var k in c.ref) {
      if (c.ref.hasOwnProperty(k)) { c.ref[k] = { name: '' }; }
    }
    c.rpClose();
    rpBrowse = [];
    c.data.result = { ok: false };
    c.data.errors = [];
  };

  c.trackUrl = function() {
    /* I6: status link is number-based; the dormant status_token is not exposed */
    var n = (c.data.result && c.data.result.number) || '';
    return window.location.origin + window.location.pathname + '?id=ptag_status&number=' + encodeURIComponent(n);
  };

  c.copy = function() {
    copyText(c.trackUrl(), function(ok) {
      $timeout(function() { c.copied = ok; });
      $timeout(function() { c.copied = false; }, 2200);
    });
  };

  function toTop() {
    try { window.scrollTo({ top: 0, behavior: 'smooth' }); } catch (e) { window.scrollTo(0, 0); }
  }

  function copyText(txt, done) {
    function fallback() {
      try {
        var el = document.createElement('textarea');
        el.value = txt;
        el.setAttribute('readonly', '');
        el.style.position = 'fixed';
        el.style.opacity = '0';
        document.body.appendChild(el);
        el.select();
        var ok = document.execCommand('copy');
        document.body.removeChild(el);
        done(!!ok);
      } catch (e) { done(false); }
    }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(txt).then(function() { done(true); }, fallback);
    } else { fallback(); }
  }
}

sp_widget.css:
/* I5 REFS: ptag_submit_w - all styling via pt-* classes from ptag_global
   (design-tokens.css + global.css). The .pt-refselect control and the
   .pt-modal picker system live in ptag_global css field, inside the
   SKIN:GLOBAL-COMPONENTS section. No widget-local styles. */


/* == I41: submit-time attachment status on the receipt == */
.pt-subatt { margin-top: 14px; }
.pt-subatt__line { display: inline-flex; align-items: center; gap: 8px; margin: 0; color: var(--pt-text-mute); font-size: var(--pt-fs-sm); }
.pt-subatt__line--err { color: var(--pt-state-declined); }


/* == I42: continue/submit subdued until the step's mandatory set is filled.
   Still clickable on purpose - the click runs validate() and lights up what
   is missing, which a disabled button cannot do. == */
.pt-btn.is-unready { opacity: .45; filter: saturate(.55); cursor: not-allowed; box-shadow: none; }
.pt-btn.is-unready:hover { filter: saturate(.55); transform: none; }

sp_widget.script:
(function() {
  /* I5 REFS: reference sources unified on the intake app lookup tables.
     - no input            -> serve option lists (I44: all four lookup tables
                              now live in x_snc_ptag_engage - fully independent)
     - action === 'search' -> whitelisted reference picker feed. term >= 2
                              chars = CONTAINS search, explicit * wildcards
                              honored (I11: split on *, AND of LIKEs; top 25);
                              shorter/empty term = browse (first 25
                              ORDERBYname). sys_id+name only.
     - action === 'create' -> validate (mandatory mirror) + scoped insert; the
       before-insert BR stamps number / state / opened_by (+ the dormant
       status_token) and auto-assigns by practice name; the receipt exposes
       the number only (I6). */
  var TABLE = 'x_snc_ptag_engage_engagement_request';
  data.result = { ok: false };
  data.errors = [];

  /* target_geo is not searchable: the form offers the controlled regions (PTAGGeo) as a select, so this
     feed never returns arbitrary cmn_location rows for it. */
  var SEARCH = {
    partner: 'customer_account',
    partner_manager: 'sys_user',
    primary_product: 'cmdb_ci_business_app'
  };

  function hasVal(v) { return v !== null && v !== undefined && String(v).trim() !== ''; }

  /* Target geo options: the controlled regions in display order (PTAGGeo reads
     x_snc_ptag_engage.target_geo_options). */
  function geoOptions() {
    try {
      return new PTAGGeo().options().map(function(o) { return { id: String(o.sys_id), name: String(o.name) }; });
    } catch (eG) { return []; }
  }

  /* Activity type options: the active choices of activity_type, by sequence. Read at run time, so a new
     choice row appears on the form and is accepted by 'create' without a code change. */
  function activityTypes() {
    var out = [];
    try {
      var at = new GlideRecord('sys_choice');
      at.addQuery('name', TABLE);
      at.addQuery('element', 'activity_type');
      at.addQuery('inactive', false);
      at.addQuery('language', 'en');
      at.orderBy('sequence');
      at.query();
      while (at.next()) { out.push({ id: String(at.getValue('value')), name: String(at.getValue('label')) }); }
    } catch (eA) { out = []; }
    return out;
  }

  if (input && input.action === 'search') {
    /* table-whitelisted; returns sys_id + name only */
    data.matches = [];
    var tbl = SEARCH[String(input.key || '')] || '';
    var term = String(input.term || '').trim();
    if (!tbl || term.length > 80) { return; }
    try {
      var s = new GlideRecord(tbl);
      if (term.length >= 2) {
        /* I11 WILDCARD: CONTAINS matching with explicit * support.
           Split the term on '*', drop empty fragments, AND one contains
           condition per fragment - encoded-query semantics:
             "corp"  -> name LIKE corp
             "1*inn" -> name LIKE 1 ^ name LIKE inn
           Operator note: encoded LIKE === CONTAINS. The CONTAINS operator
           is used because on this build 3-arg addQuery passes 'LIKE'
           through unnormalized (matches nothing), while the value-as-data
           form stays injection-safe (no string-built queries).
           An all-wildcard term (e.g. "**") behaves as browse. */
        var frags = String(term).split('*');
        var applied = 0;
        for (var fi = 0; fi < frags.length; fi++) {
          if (frags[fi] === '') { continue; }
          s.addQuery('name', 'CONTAINS', frags[fi]);
          applied++;
        }
        if (!applied) { s.addNotNullQuery('name'); }
        s.setLimit(25);
      } else {
        /* browse mode: first 25 by name */
        s.addNotNullQuery('name');
        s.setLimit(25);
      }
      s.orderBy('name');
      s.query();
      while (s.next()) { data.matches.push({ id: s.getUniqueValue(), name: String(s.getValue('name') || '').trim() }); }
    } catch (eS) { data.matches = []; }
    return;
  }

  function list(tbl, asIs) {
    var out = [];
    try {
      var g = new GlideRecord(tbl);
      /* asIs: intake-app lookups bypass the active filter. Names are
         trimmed for DISPLAY only (one intake route name carries a
         trailing space) - the sys_id binding is untouched. */
      if (!asIs && g.isValidField('active')) { g.addActiveQuery(); }
      g.orderBy('name');
      g.query();
      while (g.next()) { out.push({ id: g.getUniqueValue(), name: String(g.getValue('name') || '').trim() }); }
    } catch (eL) { out = []; }
    return out;
  }

  var MATURITY_FALLBACK = [
    { id: 'Idea', name: 'Idea' }, { id: 'in_market', name: 'In Market' },
    { id: 'pilot', name: 'Pilot' }, { id: 'prototype', name: 'Prototype' },
    { id: 'ready_for_sale', name: 'Ready For Sale' }
  ];

  if (!input) {
    data.practices = list('x_snc_ptag_engage_practice', true);
    data.routes = list('x_snc_ptag_engage_route_to_market', true);
    data.industries = list('x_snc_ptag_engage_industry');
    data.use_cases = list('x_snc_ptag_engage_partner_use_case');
    data.geos = geoOptions();
    data.activity_types = activityTypes();
    data.maturity = [];
    try {
      var mc = new GlideRecord('sys_choice');
      mc.addQuery('name', TABLE);
      mc.addQuery('element', 'in_market_status');
      mc.addQuery('inactive', false);
      mc.addQuery('language', 'en');
      mc.orderBy('sequence');
      mc.query();
      while (mc.next()) { data.maturity.push({ id: mc.getValue('value'), name: mc.getValue('label') }); }
    } catch (eM) { data.maturity = []; }
    if (!data.maturity.length) { data.maturity = MATURITY_FALLBACK; }
    data.partner_scopes = [];
    try {
      var pc = new GlideRecord('sys_choice');
      pc.addQuery('name', TABLE);
      pc.addQuery('element', 'partner_scope');
      pc.addQuery('inactive', false);
      pc.addQuery('language', 'en');
      pc.orderBy('sequence');
      pc.query();
      while (pc.next()) { data.partner_scopes.push({ id: pc.getValue('value'), name: pc.getValue('label') }); }
    } catch (ePS) { data.partner_scopes = []; }
    if (!data.partner_scopes.length) {
      data.partner_scopes = [
        { id: 'global', name: 'Global' },
        { id: 'multi_regional', name: 'Multi-regional' },
        { id: 'regional', name: 'Regional' }
      ];
    }
    return;
  }

  if (input.action !== 'create') { return; }

  var f = input.form || {};
  var errs = [];

  /* mandatory mirror: exactly the producer's mandatory=true variables */
  if (!hasVal(f.partner)) { errs.push('Parent Partner is required.'); }
  if (!hasVal(f.partner_manager)) { errs.push('Partner Manager is required.'); }
  if (!hasVal(f.practice)) { errs.push('Practice is required.'); }
  if (!hasVal(f.target_geo)) { errs.push('Where is the target geo is required.'); }
  if (!hasVal(f.short_description)) { errs.push('Short Description is required.'); }
  if (!hasVal(f.idea_description)) { errs.push('Engagement Description is required.'); }
  if (!hasVal(f.what_is_the_partners_ai_strategy)) { errs.push('What is the Partners AI Strategy? is required.'); }

  function refOk(tbl, id) {
    try { var g = new GlideRecord(tbl); return g.get(String(id)); } catch (eR) { return false; }
  }
  var REFS = [
    ['partner', 'customer_account', 'Parent Partner'],
    ['partner_manager', 'sys_user', 'Partner Manager'],
    ['practice', 'x_snc_ptag_engage_practice', 'Practice'],
    ['primary_product', 'cmdb_ci_business_app', 'Primary Product'],
    ['primary_industry', 'x_snc_ptag_engage_industry', 'Primary Target Industry'],
    ['route_to_market', 'x_snc_ptag_engage_route_to_market', 'Route to Market'],
    ['partner_use_case', 'x_snc_ptag_engage_partner_use_case', 'Primary Use Case']
  ];
  for (var i = 0; i < REFS.length; i++) {
    if (hasVal(f[REFS[i][0]]) && !refOk(REFS[i][1], f[REFS[i][0]])) {
      errs.push(REFS[i][2] + ' not recognized.');
    }
  }

  /* Target geo only takes the controlled regions. The table's save rule refuses anything else as well; this
     check answers first, with a message the requester can act on. */
  if (hasVal(f.target_geo)) {
    var geo = new PTAGGeo();
    if (!geo.isAllowed(String(f.target_geo))) {
      var gn = geo.names();
      errs.push(gn.length ? 'Target geo must be one of: ' + gn.join(', ') + '.' : 'No target geo regions are configured.');
    }
  }

  /* Activity type is optional; when given it must be one of the active choices. */
  if (hasVal(f.activity_type)) {
    var atOk = false, ats = activityTypes();
    for (var ai = 0; ai < ats.length; ai++) { if (ats[ai].id === String(f.activity_type)) { atOk = true; break; } }
    if (!atOk) { errs.push('Activity type value not recognized.'); }
  }

  var MATS = { 'Idea': 1, 'in_market': 1, 'pilot': 1, 'prototype': 1, 'ready_for_sale': 1 };
  if (hasVal(f.in_market_status) && !MATS[String(f.in_market_status)]) {
    errs.push('Maturity value not recognized.');
  }

  var SCOPES = { 'global': 1, 'multi_regional': 1, 'regional': 1 };
  if (hasVal(f.partner_scope) && !SCOPES[String(f.partner_scope)]) {
    errs.push('Partner Market Scope value not recognized.');
  }

  var tam = null;
  if (hasVal(f.tam)) {
    tam = parseFloat(String(f.tam).replace(/[$,\s]/g, ''));
    if (isNaN(tam) || tam < 0) { errs.push('TAM must be a non-negative number.'); tam = null; }
  }

  if (errs.length) { data.errors = errs; return; }

  var rec = new GlideRecord(TABLE);
  rec.initialize();
  rec.setValue('partner', String(f.partner));
  rec.setValue('partner_manager', String(f.partner_manager));
  rec.setValue('practice', String(f.practice));
  rec.setValue('target_geo', String(f.target_geo));
  rec.setValue('short_description', String(f.short_description).trim());
  rec.setValue('idea_description', String(f.idea_description));
  rec.setValue('what_is_the_partners_ai_strategy', String(f.what_is_the_partners_ai_strategy));
  if (hasVal(f.primary_product)) { rec.setValue('primary_product', String(f.primary_product)); }
  if (hasVal(f.primary_industry)) { rec.setValue('primary_industry', String(f.primary_industry)); }
  if (hasVal(f.route_to_market)) { rec.setValue('route_to_market', String(f.route_to_market)); }
  if (hasVal(f.partner_use_case)) { rec.setValue('partner_use_case', String(f.partner_use_case)); }
  if (hasVal(f.activity_type)) { rec.setValue('activity_type', String(f.activity_type)); }
  if (hasVal(f.customer_pain_points)) { rec.setValue('customer_pain_points', String(f.customer_pain_points)); }
  if (hasVal(f.value_prop)) { rec.setValue('value_prop', String(f.value_prop)); }
  if (hasVal(f.in_market_status)) { rec.setValue('in_market_status', String(f.in_market_status)); }
  rec.setValue('partner_scope', hasVal(f.partner_scope) ? String(f.partner_scope) : 'global');
  if (tam !== null) { rec.setValue('tam', tam); }
  var flags = ['pipeline', 'business_owner', 'executive_sponsor', 'corporate_alignment',
               'budget', 'has_customers', 'certified_resources'];
  for (var k = 0; k < flags.length; k++) { rec.setValue(flags[k], f[flags[k]] === true); }

  var sid = rec.insert();
  if (!sid) {
    data.errors = ['Could not create the engagement: ' + (rec.getLastErrorMessage() || 'unknown error')];
    return;
  }
  var out = new GlideRecord(TABLE);
  if (out.get(sid)) {
    data.result = { ok: true, number: out.getValue('number'), sys_id: sid };
  } else {
    data.result = { ok: true, number: '', sys_id: sid };
  }
})();
